  "inputSourceName": "project/src/S2SPublicationModuleV5.sol",
  "devdoc": {
    "events": {
      "AdminChanged(address,address)": {
        "details": "Emitted when the admin account has changed."
      },
      "BeaconUpgraded(address)": {
        "details": "Emitted when the beacon is changed."
      },
      "DealStruck(bytes32,address)": {
        "custom:deprecated": "V2 name; emitted alongside `AgreementStruck` for old indexers."
      },
      "Initialized(uint8)": {
        "details": "Triggered when the contract has been initialized or reinitialized."
      },
      "Upgraded(address)": {
        "details": "Emitted when the implementation is upgraded."
      }
    },
    "kind": "dev",
    "methods": {
      "acceptOffer(bytes32)": {
        "custom:deprecated": "V2 name; use `admit`."
      },
      "admit(bytes32)": {
        "details": "Publication admits a pending offer → agreement."
      },
      "canRead(bytes32,address)": {
        "details": "Read access for `genesis`. The safe, the genesis author and reviewers      all read a genesis once it is under an agreement or an offer; an      unknown genesis (no author) is never readable."
      },
      "canReview(bytes32,address)": {
        "details": "True iff `who` is a reviewer and `genesis` is under an agreement or offer."
      },
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor",
        "params": {
          "_factory": "The factory that approves upgrade targets. Must have        code: the value cannot be corrected after this point, and a        factory that answers nothing refuses every upgrade for good.",
          "_protocolSafe": "The protocol safe this deploy expects the factory to        name. The constructor refuses a factory that disagrees about which        safe governs it, which catches a wrong address where alone it can be        caught, before the immutable is fixed. It is not proof of ownership:        a factory answering the same safe and governed by someone else passes        it. What binds this implementation to the protocol is the protocol        safe's `setImplementation` on that factory."
        }
      },
      "factory()": {
        "details": "V4's getter, answering a constant instead of a slot. The create2      factory reads it to tell a module it governs from one it does not."
      },
      "getDealCount()": {
        "custom:deprecated": "V2 name; use `getAgreementCount`."
      },
      "getDeals(uint256,uint256)": {
        "custom:deprecated": "V2 name; use `getAgreements`."
      },
      "hasAgreement(bytes32)": {
        "details": "True iff `genesis` is currently under an agreement. Callers convert      their content reference → genesis via the shared helper before calling."
      },
      "hasDeal(bytes32)": {
        "custom:deprecated": "V2 name; use `hasAgreement`."
      },
      "hasEnded(bytes32)": {
        "details": "True iff the author has ended this genesis for this publication.      Permanent: `makeOffer` and `admit` revert for an ended genesis."
      },
      "makeOffer(bytes32,string)": {
        "details": "Append a version and place the document. Whitelisted author or safe      → agreement; anyone else → offer. Editing an existing offer just      appends another version (stays an offer). Editing content that is      already an agreement appends a version and leaves the agreement intact."
      },
      "ownerHasAgreement(address)": {
        "details": "True iff `_address` currently holds at least one agreement. Not a      publish gate: `canPublish` stays the whitelist predicate."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "reinitializeV3()": {
        "details": "Count each owner's live agreements from `agreementList` and write the      total, overwriting what was there. One call from the safe at upgrade      time, over tens of agreements.      It recomputes rather than adds, because the state a proxy arrives in      cannot say which generation wrote its counts. A proxy born under V3      was initialised by V3's `initialize`, so it never set the sentinel and      sits at nonce 1, while `_addAgreement` already counted each agreement:      an incrementing backfill would double them, and `_removeAgreement`      floors at zero rather than unwinds, leaving `ownerHasAgreement` true      for an author holding nothing. Adding nothing and writing the measured      total is correct on that proxy and on one born under V2, so no caller      has to tell the two apart.      One run either way: `reinitializer(2)` is spent on a proxy that ran      it, and `_backfilled` is set by `initialize`, so a proxy born under a      module that guard applies to is refused `AlreadyBackfilled()` rather      than silently recounted."
      },
      "reject(bytes32)": {
        "details": "The publication's verb, and reversible. `reject` never sets `_ended`:      an agreement returns to the pending offer set, an offer is declined,      and the safe may accept again."
      },
      "retract(bytes32)": {
        "details": "The author's verb, and terminal. Ending an agreement sets `_ended`      and tombstones the latest version, then removes the genesis from the      agreement set; the publication can never strike it again. Withdrawing      a pending offer that is under no agreement sets no flag: there is      nothing to end. Only the genesis author reaches this function."
      },
      "setReviewer(address,bool)": {
        "details": "Add or remove a reviewer. Idempotent; reverts on the zero address."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "stateVariables": {
      "FACTORY": {
        "details": "The factory whose approved set decides what this module may upgrade      to. Immutable: it is the same answer for every proxy over this      implementation, including one that was running V2 a transaction ago."
      },
      "_backfilled": {
        "details": "True once `agreementsHeldBy` has been counted for this proxy: set by      `initialize` on a fresh deployment, and by `reinitializeV3` when it      runs. `reinitializeV3` requires it to be false, so a fresh proxy      cannot run a backfill over counts `_addAgreement` already made. It      occupies the slot V4's `factory` did, which every V2 proxy leaves      unspent, so nothing a live proxy uses moves."
      }
    },
    "version": 1
  },
